-- 78ca2594-6e4a-4d6e-900f-ac22d7bad7f2 — A foot is short, an inch is long
UPDATE adages SET
  definition = CASE WHEN length(trim(coalesce(definition, ''))) < 100 THEN 'Everyone/thing has strengths and weaknesses; comparisons should be tempered.' ELSE definition END,
  origin = CASE WHEN length(trim(coalesce(origin, ''))) < 60 THEN 'Traditional Chinese idiom; classical background summarized in idiom references.' ELSE origin END,
  first_known_usage = COALESCE(NULLIF(trim(first_known_usage), ''), 'Common in educational and self-help paraphrase; wording varies.'),
  etymology = COALESCE(etymology, 'Units of measure stand for relative advantage: each tool has limits and uses.'),
  historical_context = COALESCE(historical_context, 'Used to temper ranking contests and invidious comparison.'),
  interpretation = COALESCE(interpretation, 'Competitive superiority depends on the task; humility follows from that fact.'),
