-- fa0fc8a2-4943-4d73-9a85-21857a5805ad — Forget the fishing gear as soon as the fish is caught
UPDATE adages SET
  definition = CASE WHEN length(trim(coalesce(definition, ''))) < 100 THEN 'Discard the method or helper once the result is achieved; can imply ingratitude or forgetting the process that made success possible.' ELSE definition END,
  origin = CASE WHEN length(trim(coalesce(origin, ''))) < 60 THEN 'Traditional Chinese chengyu; glossed in standard idiom dictionaries.' ELSE origin END,
  first_known_usage = COALESCE(NULLIF(trim(first_known_usage), ''), 'Classical/literary background summarized in references; English metaphors vary.'),
  etymology = COALESCE(etymology, 'Fish stands for the outcome; gear stands for means and mentors that enabled it.'),
  historical_context = COALESCE(historical_context, 'Used to criticize ingratitude and short memory after success.'),
  interpretation = COALESCE(interpretation, 'Ends matter, but erasing helpers erodes trust for the next cycle.'),
  modern_practicality = COALESCE(modern_practicality, 'Document dependencies, thank contributors, and preserve playbooks—not only trophies.'),
  updated_at = now()
WHERE id = 'fa0fc8a2-4943-4d73-9a85-21857a5805ad'::uuid AND deleted_at IS NULL;
